import { readFileSync, readdirSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { buildRecords, ID_PATTERN, serialize } from "../../scripts/provenance/records.mjs";

// src/content/assets/ is generated by `npm run provenance` (exiftool, local only). These checks
// run in CI without exiftool: the committed records must match their sources and the rules.
const root = new URL("../../", import.meta.url);
const read = (path: string) => readFileSync(new URL(path, root), "utf8");
const manifest = JSON.parse(read("design/renders/manifest.json"));
const editorial = JSON.parse(read("design/renders/provenance.json"));
interface Localized {
  en: string;
  ar: string;
}
interface ProvenanceRecord {
  id: string;
  digitalSourceType: string;
  aircraft?: string;
  caption: Localized;
  alt: Localized;
  metadataRetained: { on: string };
}
const records = buildRecords(manifest, editorial) as unknown as ProvenanceRecord[];
const committed = readdirSync(new URL("src/content/assets/", root)).filter((f) =>
  f.endsWith(".json"),
);

describe("provenance records", () => {
  it("are up to date with manifest.json and provenance.json (run npm run provenance)", () => {
    expect(committed.sort()).toEqual(records.map((r) => `${r.id}.json`).sort());
    for (const record of records) {
      expect(read(`src/content/assets/${record.id}.json`), record.id).toBe(serialize(record));
    }
  });

  it("cover every render in design/renders, named by asset ID", () => {
    const renders = readdirSync(new URL("design/renders/", root))
      .filter((f) => /\.(jpe?g|png|avif|webp)$/i.test(f))
      .map((f) => f.replace(/\.[^.]+$/, ""));
    expect(records.map((r) => r.id).sort()).toEqual(renders.sort());
    for (const r of records) expect(r.id).toMatch(ID_PATTERN);
  });

  it("say what is shown and that it is generated (PRD §14)", () => {
    for (const r of records) {
      if (!r.digitalSourceType.endsWith("digitalCapture")) {
        expect(r.alt.en, r.id).toMatch(/^Generated /);
        expect(r.alt.ar, r.id).toContain("مولّدة");
        expect(r.caption.en, r.id).toMatch(/^GENERATED /);
      }
    }
  });

  it("generated aerials state there was no aircraft (03)", () => {
    for (const r of records.filter((r) => r.id.startsWith("MKN-AER-"))) {
      expect(r.aircraft, r.id).toBe("none");
      expect(r.caption.en, r.id).toContain("NO AIRCRAFT");
    }
  });

  it("never claim metadata on a web derivative (CLAUDE.md)", () => {
    for (const r of records) expect(r.metadataRetained.on, r.id).toBe("master");
  });

  it("reject sources that disagree", () => {
    const missing = { ...editorial, assets: { ...editorial.assets } };
    delete missing.assets["MKN-AER-FLT01-A"];
    expect(() => buildRecords(manifest, missing)).toThrow(/MKN-AER-FLT01-A: missing/);
  });
});
